#!/usr/bin/env python3
"""Generate fixed real-CG/solid-harmonic tables; requires NumPy, Torch, e3nn."""
from pathlib import Path

import numpy as np
import torch
from e3nn import o3

ROOT = Path(__file__).resolve().parents[1]


def main():
    output = [
        '/* GPUMD, LGPL-3.0-or-later. Real Clebsch-Gordan coefficients in the',
        '   e3nn component-normalized real spherical-harmonic convention.',
        '   Generated by tests_pytest/generate_spin_tables.py. */',
        '#pragma once',
        'namespace nep_spin {',
        'struct Coupling { int l1, l2, lout, a, b, m; double value; };',
        'static const Coupling couplings[] = {',
    ]
    for l1 in range(5):
        for l2 in range(5):
            for lo in range(abs(l1-l2), min(l1+l2, 4)+1):
                cg = o3.wigner_3j(l1, l2, lo, dtype=torch.float64).numpy()*np.sqrt(2*lo+1)
                for a, b, m in zip(*np.where(np.abs(cg) > 1e-14)):
                    output.append(f'  {{{l1}, {l2}, {lo}, {a}, {b}, {m}, {cg[a,b,m]:.17g}}},')
    output += [
        '};',
        'struct Harmonic { int component, x, y, z; double value; };',
        'static const Harmonic harmonics[] = {',
    ]
    # Recover the sparse homogeneous polynomials, not an approximation on a sphere.
    # An overdetermined full-rank monomial system is sufficient for ranks <= 4.
    xyz = np.random.default_rng(9732).normal(size=(140, 3))
    for rank in range(5):
        powers = [(a,b,rank-a-b) for a in range(rank+1) for b in range(rank-a+1)]
        matrix = np.array([np.prod(xyz**p, axis=1) for p in powers]).T
        values = o3.spherical_harmonics(
            rank, torch.tensor(xyz), False, normalization='component').numpy()
        coefficients = np.linalg.lstsq(matrix, values, rcond=None)[0]
        assert np.max(np.abs(matrix@coefficients-values)) < 2e-11
        for k, power in enumerate(powers):
            for m in range(2*rank+1):
                if abs(coefficients[k,m]) > 1e-12:
                    output.append(f'  {{{rank*rank+m}, {power[0]}, {power[1]}, {power[2]}, '
                                  f'{coefficients[k,m]:.17g}}},')
    output += ['};', '} // namespace nep_spin', '']
    (ROOT/'src/force/nep_spin/spin_tables.cuh').write_text('\n'.join(output))


if __name__ == '__main__':
    main()
